<?php $r = $args['record']; $d = $r['data']; ?>
<section class="story-section"><div class="story-copy"><h2><?php echo 'msc_person' === $r['type'] ? 'Biography' : 'Overview'; ?></h2><div class="prose"><?php echo msc_screen_overview( $r ); ?></div></div><aside class="details-panel"><p class="eyebrow"><?php echo 'msc_person' === $r['type'] ? 'Profile details' : 'Details'; ?></p><?php msc_screen_facts( $r, $args['facts'] ?? array() ); echo \MSC\EntityCatalog::sidebar( $r ); ?><?php foreach ( array( 'director' => 'Director (original credit)', 'writers' => 'Writing credits', 'cast' => 'Cast notes' ) as $key => $label ) { if ( ! empty( $d[ $key ] ) && ( 'director' !== $key || empty( $d['directors'] ) ) && ( 'writers' !== $key || empty( $d['screenwriters'] ) ) ) { echo '<h3>' . esc_html( $label ) . '</h3><div class="prose small">' . wp_kses_post( wpautop( $d[ $key ] ) ) . '</div>'; } } ?></aside></section>
